P = [
 dict(pmid='43050621', doi='10.1080/15459624.2026.2737099', journal='J Occup Environ Hyg', title='Stage-resolved PM(2.5), PM(10), and VOC concentrations during field-simulated ski waxing and tuning: A pilot study with an exploratory worker survey.', tier='B', basis='Low-cost sensor / network', short='Utah ski-waxing pilot with low-cost optical PM sensor + PID: application stage PM2.5 456-771 ug/m3; 8% of 50 workers have dedicated exhaust', design='Pilot field measurement', pm='Near-field PM2.5 and PM10 from a low-cost optical sensor, total VOC from a PID, by waxing/tuning stage', geo='USA (Utah)', endpoint='Stage-resolved PM2.5, PM10 and TVOC concentrations; worker survey on wax type and ventilation', affil='University of Utah, USA; University of Utah, USA', n='Two-phase pilot: survey of 50 ski-industry workers (69.2% of those knowing their wax used fluorocarbon wax; 8% had effective dedicated exhaust) and field-simulated waxing and tuning with three block waxes over four stages, measured with a low-cost optical PM sensor and a PID. Wax application gave the highest run-level means, PM2.5 about 456-771 ug/m3 and PM10 602-1,045 ug/m3; brushing and scraping were intermediate; ironing raised PM only for the fluorinated race wax at 160 C; tuning was far lower. Weakness: wax type and iron temperature are confounded, the sensor was not reported as gravimetrically corrected for wax aerosol, and runs are few. Relevance: a clean case of an LCS used for stage-resolved occupational profiling, where the uncorrected mass scale is the main threat.', sub=corpus.OCC),
 dict(pmid='43048551', doi='10.1016/j.atmosenv.2026.122035', journal='Atmos Environ (1994)', title='Exposure to particulate matter, black carbon, and ultrafine particles at Philadelphia subway stations.', tier='B', basis='Lab / research instrument', short='Villanova Philadelphia subway: belowground PM2.5 5.1x, BC 16.5x, UFP LDSA 1.9x street level; 15th St PM2.5 157 ug/m3', design='Field measurement', pm='Concurrent belowground and street-level PM2.5, black carbon and ultrafine lung-deposited surface area at three stations', geo='USA (Philadelphia)', endpoint='Microenvironment concentration ratios; PM2.5 risk quotient', affil='Villanova University, USA; Villanova University, USA', n='Concurrent belowground and street-level measurements at three Philadelphia subway stations, summer 2023. Belowground means exceeded street level about 5.1x for PM2.5, 16.5x for black carbon and 1.9x for UFP lung-deposited surface area; 15th Street was highest (PM2.5 156.8 +/- 25.3 ug/m3; LDSA 56.7 +/- 21.2 um2/cm3). A PM2.5 risk quotient below 1 was reported for commuters. Weakness: one season, three stations, no instrument models in the abstract; iron-rich subway PM makes optical mass ambient-calibrated instruments unreliable, and the low-risk conclusion rests on commuter-duration averaging and ignores workers. Relevance: subway platforms are a microenvironment where personal and low-cost monitors read high and need aerosol-specific correction.', sub=corpus.OCC),
 dict(pmid='43048511', doi='10.1177/22799036261500249', journal='J Public Health Res', title='Internet of Things (IoT) in environmental public health: Monitoring environmental hazards and supporting public health action.', tier='B', basis='Review / no primary exposure', short='North South University structured narrative review of 45 sources on IoT in environmental public health; PM2.5 sensing most mature', design='Narrative review', pm='IoT environmental sensors, chiefly PM2.5 low-cost networks; ML calibration and drift', geo='Global / multi-region', endpoint='Evidence maturity across sensor performance, exposure characterisation, early warning and health impact', affil='North South University, Bangladesh; North South University, Bangladesh', n='Structured narrative review of 45 sources (PubMed/PMC, IEEE Xplore, ScienceDirect, Google Scholar, citation tracking) grading IoT environmental-health evidence by maturity across technical validity, data quality, interoperability, security, privacy, equity, cost and public-health utility. Evidence is strongest for field-validated PM2.5 sensing and exposure characterisation; ML calibration reduces drift when retrained across seasons or networks, but transfer is pollutant- and site-dependent; evidence that automated sensor alerts improve population health is scant. Weakness: single-author synthesis of a small, non-systematic source set with no risk-of-bias assessment, so maturity grades are judgement. Relevance: restates the gap this watch keeps finding - networks are validated as instruments, almost never as interventions with measured health or behavioural outcomes.', sub=corpus.SENS),
 dict(pmid='', doi='10.3390/atmos17111144', journal='Atmosphere', title='Chemical Characterization and Source Apportionment of PM2.5 During Autumn and Winter in an Industrial High-Tech Zone of the Yangtze River Delta, China', tier='C', basis='Lab / research instrument', short='Nanjing Institute YRD industrial high-tech zone autumn-winter PM2.5 PMF: industry 39.6%, mobile 14.6%, ammonium nitrate drives episodes', design='Source apportionment', pm='Filter PM2.5 water-soluble ions and constituents, Nov 2024-Jan 2025; PMF with secondary reallocation by inventory', geo='China (Yangtze River Delta)', endpoint='Source contributions to PM2.5; SOR/NOR', affil='Nanjing Institute of Environmental Sciences, China; Nanjing Institute of Environmental Sciences, China', n='Intensive PM2.5 sampling in an industrial high-tech zone of the western Yangtze River Delta, November 2024-January 2025. Nitrate, sulfate and ammonium made up 62.8-91% of water-soluble ions; mean SOR 0.365, NOR 0.207; NH4+ and NO3- rose significantly from clean to polluted periods, implicating ammonium nitrate. PMF resolved seven factors; after reallocating secondary aerosol to primary sources via the local inventory, industry contributed 39.6%, mobile 14.6%, fugitive dust 11.9%, cooking 11.9%, coal 11.4%. Weakness: one site, one season, and the reallocation step imports inventory assumptions, so the industrial share is partly model-defined. Relevance: nitrate-driven episodes are where hygroscopic-growth errors in optical sensors peak, so this composition context matters for any local network.', sub=corpus.EXPO),
]
